    overlay.onclick=async event=>{const eventBrush=event.target.closest?.('[data-ai-event-brush]'),eventPlace=event.target.closest?.('[data-ai-event-place]');if(eventBrush){event.preventDefault();const id=eventBrush.dataset.aiEventBrush,entry=eventCollections.get(id),section=eventBrush.closest('.lvx-rich-result'),contract=globalThis.LuviaVerifiedEventIntelligenceContractV1;for(const control of eventBrush.parentElement?.querySelectorAll('[data-ai-event-brush]')||[])control.classList.toggle('is-active',control===eventBrush);const brush=contract?.reads?.brushGraph?.(entry?.graph||{},{from:eventBrush.dataset.eventFrom||null,to:eventBrush.dataset.eventTo||null});mountEventMap(section,id,brush?.eventIds||[]);return}if(eventPlace){event.preventDefault();const token=String(eventPlace.dataset.aiEventPlace||''),separator=token.indexOf(':'),id=separator<0?'':token.slice(0,separator),eventId=separator<0?'':token.slice(separator+1),entry=eventCollections.get(id),subject=eventVenueSubject(entry?.items.find(item=>item.eventClaimId===eventId));if(subject)openPlaceSubject(subject);return}const placeButton=event.target.closest?.('[data-ai-place-open]');if(placeButton){event.preventDefault();openPlaceSubject(placeSubjects.get(placeButton.dataset.aiPlaceOpen));return}const readRetryButton=event.target.closest?.('[data-ai-read-retry]'),readRefineButton=event.target.closest?.('[data-ai-read-refine]');if(readRetryButton||readRefineButton){event.preventDefault();const id=readRetryButton?.dataset.aiReadRetry||readRefineButton?.dataset.aiReadRefine,entry=readRecoveries.get(id);if(!entry)return;if(readRefineButton){input.value=entry.query||activeConversation?.request||'';input.focus();setState('empty','Wunsch übernommen. Ergänze oder präzisiere ihn; es wurde nichts verändert.');return}if(readRetryButton.disabled)return;readRetryButton.disabled=true;appendMessage('assistant',`${entry.owner} wird mit demselben, weiterhin read-only Wunsch erneut geprüft.`,{source:'Owner-Read Recovery · keine Mutation'});setState('loading','Der zuständige Owner-Read wird erneut ausgeführt …');await runActiveSequence();return}const continuationButton=event.target.closest?.('[data-ai-sequence-continue]');if(continuationButton){event.preventDefault();const entry=continuations.get(continuationButton.dataset.aiSequenceContinue);if(!entry||continuationButton.disabled)return;continuationButton.disabled=true;await advanceConversation('explicit-continue',entry);return}const confirmButton=event.target.closest?.('[data-ai-confirm]'),cancelButton=event.target.closest?.('[data-ai-cancel-confirmation]'),retryButton=event.target.closest?.('[data-ai-action-retry]'),undoButton=event.target.closest?.('[data-ai-action-undo]');if(confirmButton||cancelButton){event.preventDefault();const id=confirmButton?.dataset.aiConfirm||cancelButton?.dataset.aiCancelConfirmation,entry=confirmations.get(id),card=event.target.closest('[data-ai-confirmation-card]'),controls=[...(card?.lastElementChild?.children||[])];if(!entry)return;controls.forEach(control=>control.disabled=true);setState('loading',confirmButton?'Bestätigter Owner Command wird ausgeführt …':'Vorbereitete Aktion wird verworfen …');try{const receipt=confirmButton?await actionRuntime().execute(entry.actionId,{}, {ledgerId:entry.ledgerId,userGesture:true,confirmed:true}):actionRuntime().cancel(entry.ledgerId);appendRichResult(receipt);confirmations.delete(id);if(cancelButton&&entry.sourceButton)entry.sourceButton.disabled=false;card?.remove();setState(receipt.evidence?.status==='failed'||receipt.evidence?.status==='outcome_unknown'?'error':'success',receipt.evidence?.status==='outcome_unknown'?'Der externe Ausgang wird vom zuständigen Owner abgeglichen.':receipt.evidence?.status==='compensated'?'Das Undo Receipt steht im Verlauf.':'Das Owner Receipt steht im Verlauf.');if(confirmButton&&!entry.compensatesLedgerId&&successfulReceipt(receipt))await advanceConversation('owner-receipt',entry)}catch(error){controls.forEach(control=>control.disabled=false);appendMessage('assistant',error.message,{error:true});setState('error','Die bestätigte Aktion konnte nicht sicher abgeschlossen werden.')}return}if(undoButton){event.preventDefault();const ledgerId=undos.get(undoButton.dataset.aiActionUndo);if(!ledgerId)return;undoButton.disabled=true;setState('loading','Der zuständige Owner bereitet die exakte Gegenaktion vor …');try{const prepared=actionRuntime().prepareUndo(ledgerId,{userGesture:true,surface});appendConfirmation(prepared.result,{sourceButton:undoButton,compensatesLedgerId:ledgerId});setState('attention','Bitte prüfe auch das Undo und bestätige es ausdrücklich.')}catch(error){undoButton.disabled=false;appendMessage('assistant',error.message,{error:true});setState('error','Für diese Aktion ist kein sicherer automatischer Undo-Pfad verfügbar.')}return}if(retryButton){event.preventDefault();const ledgerId=recoveries.get(retryButton.dataset.aiActionRetry);if(!ledgerId)return;retryButton.disabled=true;setState('loading','Der eindeutig fehlgeschlagene Owner Command wird mit demselben Schlüssel wiederholt …');try{const receipt=await actionRuntime().retry(ledgerId);appendRichResult(receipt);setState(receipt.evidence?.status==='failed'?'error':'success','Recovery-Receipt steht im Verlauf.')}catch(error){appendMessage('assistant',error.message,{error:true});setState('error','Die Aktion darf nicht automatisch wiederholt werden.')}return}const ownerButton=event.target.closest?.('[data-ai-owner-action]');if(ownerButton){event.preventDefault();const entry=ownerActions.get(ownerButton.dataset.aiOwnerAction),offer=entry?.offer,subject=entry?.subject;if(!offer||ownerButton.disabled)return;if(offer.actionId==='places.place.plan'&&!offer.payload?.fields?.planned_at&&subject&&globalThis.LuviaJourneySuggestions?.openResults){globalThis.LuviaUI?.closeTop?.('places-transfer');queueMicrotask(()=>globalThis.LuviaJourneySuggestions.openResults({places:[subject],selectedId:subject.providerPlaceId,source:'ai-chat',query:'Aus dem Luvia Compass zur Timeline'}));return}ownerButton.disabled=true;ownerButton.setAttribute('aria-busy','true');setState('loading',`${offer.owner} erstellt eine sichtbare Vorschau …`);try{const prepared=actionRuntime().prepare(offer.actionId,offer.payload,{userGesture:true,surface});if(prepared.requiresConfirmation){appendRichResult(prepared.result,{sourceButton:ownerButton});setState('attention','Bitte prüfe die Folgen und bestätige oder verwirf die Aktion.')}else{const receipt=await actionRuntime().execute(offer.actionId,{}, {ledgerId:prepared.ledgerId,userGesture:true});appendRichResult(receipt);const failed=receipt.evidence?.status==='failed';if(failed)ownerButton.disabled=false;setState(failed?'error':'success',failed?'Die Owner-Aktion konnte nicht abgeschlossen werden.':'Owner-Aktion bestätigt; das Receipt steht im Verlauf.');if(!failed&&successfulReceipt(receipt))await advanceConversation('owner-receipt',entry)}}catch(error){ownerButton.disabled=false;appendMessage('assistant',error.message,{error:true});setState('error','Die Owner-Aktion konnte nicht sicher vorbereitet werden.')}finally{ownerButton.removeAttribute('aria-busy')}return}const prompt=event.target.closest?.('[data-ai-prompt]'),suggestion=event.target.closest?.('[data-ai-suggestion]');if(!prompt&&!suggestion)return;input.value=prompt?prompts[Number(prompt.dataset.aiPrompt)]?.value||'':suggestions.get(suggestion.dataset.aiSuggestion)||'';input.focus();setState('empty','Vorschlag übernommen. Du kannst den Wunsch noch anpassen.')};
